mkdir -p /tmp/claude-0/-home-user-Claudinite/afb153e4-4667-5d4d-8429-810010ddee58/scratchpad && cat > /tmp/claude-0/-home-user-Claudinite/afb153e4-4667-5d4d-8429-810010ddee58/scratchpad/digest.mjs <<'EOF'
import { createInterface } from 'node:readline';
const rl = createInterface({ input: process.stdin });
const out = [];
const pending = new Map();
let toolTotal = 0, first=null, last=null;
const toolTimes = [];
for await (const line of rl) {
  if (!line.trim()) continue;
  let e; try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp;
  if (ts) { if (!first) first = ts; last = ts; }
  const m = e.message;
  if (!m) continue;
  if (m.role === 'user') {
    const c = m.content;
    if (typeof c === 'string') out.push(`[${ts}] USER: ${c.slice(0,1500)}`);
    else if (Array.isArray(c)) for (const b of c) {
      if (b.type === 'text') out.push(`[${ts}] USER: ${b.text.slice(0,1500)}`);
      else if (b.type === 'tool_result') {
        const st = pending.get(b.tool_use_id);
        if (st) {
          const dur = (new Date(ts) - new Date(st.ts))/1000;
          toolTotal += dur; toolTimes.push({name: st.name, dur, inp: st.inp});
          pending.delete(b.tool_use_id);
        }
        const txt = typeof b.content === 'string' ? b.content : JSON.stringify(b.content);
        if (b.is_error) out.push(`[${ts}]   ERR: ${(txt||'').slice(0,600)}`);
      }
    }
  } else if (m.role === 'assistant') {
    for (const b of m.content || []) {
      if (b.type === 'text' && b.text.trim()) out.push(`[${ts}] ASSISTANT: ${b.text.slice(0,2000)}`);
      else if (b.type === 'tool_use') {
        pending.set(b.id, { ts, name: b.name, inp: JSON.stringify(b.input).slice(0,300) });
        out.push(`[${ts}] TOOL ${b.name}: ${JSON.stringify(b.input).slice(0,300)}`);
      }
    }
  }
}
